package com.nageoffer.ai.ragent.triage.eval;

import com.nageoffer.ai.ragent.triage.model.*;
import lombok.*;
import java.util.*;

public class TriageEvalNormalizer {
    public NormalizedEvalResult normalize(String caseId,TriageContext context){TriageContext c=context==null?new TriageContext():context;c.ensureCollections();return NormalizedEvalResult.builder().caseId(caseId).facts(new ArrayList<>(c.getFactHistory())).slotValues(normalizeSlotValues(c)).answeredSlots(toNames(c.getAnsweredSlots())).lastAskedSlots(toNames(c.getLastAskedSlots())).pendingSlots(toNames(c.getPendingSlots())).riskLevel(normalizeRiskLevel(c.getRiskAssessment())).riskScore(c.getRiskAssessment()==null?null:c.getRiskAssessment().getScore()).nextAction(c.getNextAction()==null?null:c.getNextAction().name()).questionPlan(normalizeQuestionPlan(c.getQuestionPlan())).finalReply(c.getFinalReply()).understanding(normalizeUnderstanding(c.getLatestTurnUnderstanding())).reducer(normalizeReducer(c.getLatestStateReducerResult())).planner(PlannerSnapshot.builder().candidateGaps(normalizeQuestionGaps(c.getCandidateQuestionGaps())).selectedGaps(normalizeQuestionGaps(c.getSelectedQuestionGaps())).suppressedGaps(normalizeQuestionGaps(c.getSuppressedQuestionGaps())).askabilityDecisions(normalizeAskability(c.getAskabilityDecisions())).build()).riskDecision(normalizeRiskDecision(c.getRiskDecision())).history(normalizeHistory(c)).build();}
    private Map<String,SlotSnapshot> normalizeSlotValues(TriageContext c){return normalizeSlots(c==null||c.getSlotState()==null?null:c.getSlotState().getSlots());} private Map<String,SlotSnapshot> normalizeReducedSlotValues(StateReducerResult r){return normalizeSlots(r==null?null:r.getReducedSlots());}
    private Map<String,SlotSnapshot> normalizeSlots(Map<SlotCode,SlotValue> slots){Map<String,SlotSnapshot> result=new LinkedHashMap<>();if(slots==null)return result;for(Map.Entry<SlotCode,SlotValue> e:slots.entrySet())if(e.getKey()!=null&&e.getValue()!=null)result.put(e.getKey().name(),SlotSnapshot.builder().value(e.getValue().getValue()).status(e.getValue().getStatus()==null?null:e.getValue().getStatus().name()).evidence(e.getValue().getEvidence()).build());return result;}
    private List<String> toNames(List<SlotCode> codes){List<String> result=new ArrayList<>();if(codes!=null)for(SlotCode code:codes)if(code!=null)result.add(code.name());return result;}
    private String normalizeRiskLevel(RiskLevel r){if(r==null||r.getLevel()==null)return null;return switch(r.getLevel()){case 1->"LOW";case 2->"MEDIUM";case 3,4->"HIGH";default->"UNKNOWN";};}
    private QuestionPlanSnapshot normalizeQuestionPlan(QuestionPlan q){if(q==null)return null;return QuestionPlanSnapshot.builder().nextSlotsToAsk(toNames(q.getNextSlotsToAsk())).pendingSlots(toNames(q.getPendingSlots())).priorityReason(q.getPriorityReason()).askCount(q.getAskCount()).followUpMode(q.getFollowUpMode()).build();}
    private UnderstandingSnapshot normalizeUnderstanding(TurnUnderstanding u){if(u==null)return null;return UnderstandingSnapshot.builder().intent(normalizeIntent(u.getIntent())).primaryComplaint(u.getPrimaryComplaint()==null?null:u.getPrimaryComplaint().getValue()).answeredSlots(normalizeAnsweredSlots(u.getAnsweredSlots())).riskSignals(normalizeRiskSignals(u.getRiskSignals())).corrections(normalizeCorrections(u.getCorrections())).build();}
    private ReducerSnapshot normalizeReducer(StateReducerResult r){if(r==null)return null;return ReducerSnapshot.builder().reducedSlotValues(normalizeReducedSlotValues(r)).complaintTruth(r.getComplaintTruth()==null?null:r.getComplaintTruth().getValue()).answeredSlots(toNames(r.getAnsweredSlots())).pendingCandidates(toNames(r.getPendingCandidates())).accumulatedRiskSignals(normalizeRiskSignals(r.getAccumulatedRiskSignals())).correctionCount(size(r.getCorrectionLog())).build();}
    private RiskDecisionSnapshot normalizeRiskDecision(RiskDecision r){if(r==null)return null;return RiskDecisionSnapshot.builder().decisionType(r.getDecisionType()==null?null:r.getDecisionType().name()).shouldInterrupt(r.getShouldInterrupt()).needsMoreInfo(r.getNeedsMoreInfo()).confirmedRiskGaps(normalizeRiskGaps(r.getConfirmedRiskGaps())).suspectedRiskGaps(normalizeRiskGaps(r.getSuspectedRiskGaps())).unresolvedRiskGaps(normalizeRiskGaps(r.getUnresolvedRiskGaps())).build();}
    private HistorySnapshot normalizeHistory(TriageContext c){String finalPrimaryComplaint=text(c.getFinalPrimaryComplaint());String reducerComplaintTruth=normalizeReducerComplaintTruth(c.getLatestStateReducerResult());return HistorySnapshot.builder().turnUnderstandingHistoryCount(size(c.getTurnUnderstandingHistory())).stateReducerHistoryCount(size(c.getStateReducerHistory())).riskDecisionHistoryCount(size(c.getRiskDecisionHistory())).finalPrimaryComplaint(finalPrimaryComplaint).reducerComplaintTruth(reducerComplaintTruth).complaintTruthSynchronized(isComplaintTruthSynchronized(finalPrimaryComplaint,reducerComplaintTruth)).build();}
    private String normalizeReducerComplaintTruth(StateReducerResult reducer){return reducer==null||reducer.getComplaintTruth()==null?null:text(reducer.getComplaintTruth().getValue());}
    private Boolean isComplaintTruthSynchronized(String finalPrimaryComplaint,String reducerComplaintTruth){if(finalPrimaryComplaint==null&&reducerComplaintTruth==null)return true;if(finalPrimaryComplaint==null||reducerComplaintTruth==null)return false;return finalPrimaryComplaint.equals(reducerComplaintTruth);}
    private List<String> normalizeAnsweredSlots(List<AnsweredSlotUnderstanding> items){List<String> r=new ArrayList<>();if(items==null)return r;for(AnsweredSlotUnderstanding i:items)if(i!=null&&i.getSlot()!=null)r.add(i.getSlot().name()+(text(i.getNormalizedValue())!=null?"="+text(i.getNormalizedValue()):text(i.getRawValue())!=null?"="+text(i.getRawValue()):"")+(i.getAssertion()==null?"":"|"+i.getAssertion().name()));return r;}
    private List<String> normalizeRiskSignals(List<RiskSignalUnderstanding> items){List<String> r=new ArrayList<>();if(items==null)return r;for(RiskSignalUnderstanding i:items)if(i!=null&&i.getType()!=null)r.add(i.getType().name()+(i.getAssertion()==null?"":"|"+i.getAssertion().name())+(i.getSeverityHint()==null?"":"|"+i.getSeverityHint().name()));return r;}
    private List<String> normalizeCorrections(List<CorrectionUnderstanding> items){List<String> r=new ArrayList<>();if(items==null)return r;for(CorrectionUnderstanding i:items)if(i!=null&&i.getTarget()!=null)r.add((i.getSlot()!=null?i.getSlot().name()+"|":"")+i.getTarget().name()+(text(i.getRejectValue())==null?"":"|reject="+text(i.getRejectValue()))+(text(i.getConfirmValue())==null?"":"|confirm="+text(i.getConfirmValue())));return r;}
    private List<String> normalizeQuestionGaps(List<QuestionGap> items){List<String> r=new ArrayList<>();if(items==null)return r;for(QuestionGap i:items)if(i!=null&&i.getSlot()!=null)r.add(i.getSlot().name()+(i.getGapType()==null?"":"|"+i.getGapType().name())+(i.getSource()==null?"":"|"+i.getSource().name())+(i.getAskable()==null?"":"|askable="+i.getAskable()));return r;}
    private List<String> normalizeAskability(List<AskabilityDecision> items){List<String> r=new ArrayList<>();if(items==null)return r;for(AskabilityDecision i:items)if(i!=null&&i.getSlot()!=null)r.add(i.getSlot().name()+(i.getAskable()==null?"":"|askable="+i.getAskable())+(i.getReason()==null?"":"|"+i.getReason().name())+(text(i.getDetail())==null?"":"|detail="+text(i.getDetail())));return r;}
    private List<String> normalizeRiskGaps(List<RiskGap> items){List<String> r=new ArrayList<>();if(items==null)return r;for(RiskGap i:items)if(i!=null&&i.getSlot()!=null)r.add(i.getSlot().name()+(i.getRelatedSignalType()==null?"":"|"+i.getRelatedSignalType().name())+(i.getSignalStatus()==null?"":"|"+i.getSignalStatus().name()));return r;}
    private String normalizeIntent(TurnIntent intent){return intent==null?null:intent==TurnIntent.ANSWER_FOLLOW_UP?"ANSWER_SLOT":intent.name();}
    private String text(String s){return s==null||s.isBlank()?null:s;} private int size(List<?> items){return items==null?0:items.size();}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class NormalizedEvalResult{private String caseId;@Builder.Default private List<Fact> facts=new ArrayList<>();@Builder.Default private Map<String,SlotSnapshot> slotValues=new LinkedHashMap<>();@Builder.Default private List<String> answeredSlots=new ArrayList<>();@Builder.Default private List<String> lastAskedSlots=new ArrayList<>();@Builder.Default private List<String> pendingSlots=new ArrayList<>();private String riskLevel;private Double riskScore;private String nextAction;private QuestionPlanSnapshot questionPlan;private String finalReply;private UnderstandingSnapshot understanding;private ReducerSnapshot reducer;private PlannerSnapshot planner;private RiskDecisionSnapshot riskDecision;private HistorySnapshot history;}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class SlotSnapshot{private String value;private String status;private String evidence;}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class QuestionPlanSnapshot{@Builder.Default private List<String> nextSlotsToAsk=new ArrayList<>();@Builder.Default private List<String> pendingSlots=new ArrayList<>();private String priorityReason;private Integer askCount;private Boolean followUpMode;}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class UnderstandingSnapshot{private String intent;private String primaryComplaint;@Builder.Default private List<String> answeredSlots=new ArrayList<>();@Builder.Default private List<String> riskSignals=new ArrayList<>();@Builder.Default private List<String> corrections=new ArrayList<>();}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class ReducerSnapshot{@Builder.Default private Map<String,SlotSnapshot> reducedSlotValues=new LinkedHashMap<>();private String complaintTruth;@Builder.Default private List<String> answeredSlots=new ArrayList<>();@Builder.Default private List<String> pendingCandidates=new ArrayList<>();@Builder.Default private List<String> accumulatedRiskSignals=new ArrayList<>();private Integer correctionCount;}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class PlannerSnapshot{@Builder.Default private List<String> candidateGaps=new ArrayList<>();@Builder.Default private List<String> selectedGaps=new ArrayList<>();@Builder.Default private List<String> suppressedGaps=new ArrayList<>();@Builder.Default private List<String> askabilityDecisions=new ArrayList<>();}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class RiskDecisionSnapshot{private String decisionType;private Boolean shouldInterrupt;private Boolean needsMoreInfo;@Builder.Default private List<String> confirmedRiskGaps=new ArrayList<>();@Builder.Default private List<String> suspectedRiskGaps=new ArrayList<>();@Builder.Default private List<String> unresolvedRiskGaps=new ArrayList<>();}
    @Data @NoArgsConstructor @AllArgsConstructor @Builder public static class HistorySnapshot{private Integer turnUnderstandingHistoryCount;private Integer stateReducerHistoryCount;private Integer riskDecisionHistoryCount;private String finalPrimaryComplaint;private String reducerComplaintTruth;private Boolean complaintTruthSynchronized;}
}
